def shell(title,desc,content,section='home'):
 nav=''.join(nav_dropdown(key, section==key) if key in NAV_GROUPS else f'<a {"aria-current=page" if section==key else ""} href="{url}">{label}</a>' for key,url,label in [('home','/','Home'),('soc','/soc-architecture/','SoC Architecture'),('lab','/width-vs-frequency/','Interactive lab'),('pcie','/pcie/','PCIe series'),('about','/about/','About')])
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | SoC PPALS</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="theme-color" content="#102d31"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script defer src="/site.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><a class="brand" href="/" aria-label="SoC PPALS home"><span class="brandmark">▦</span><span>SoC <b>PPALS</b><small>ARCHITECTURE · SYSTEMS · TRADE OFFS</small></span></a><button class="menutoggle" aria-expanded="false" aria-controls="nav">Menu</button><nav id="nav" aria-label="Main navigation">{nav}</nav></header><main id="main">{content}</main><footer><div><a class="brand" href="/">SoC <b>PPALS</b></a><p>Architecture decisions, explained through real engineering questions.</p><small>© 2026 Srinivas Gaddam. Personal technical writing.<br>Views expressed here are personal and do not represent an employer.</small></div><div class="footlinks"><a href="/soc-architecture/">SoC Architecture</a><a href="/width-vs-frequency/">Width vs Frequency</a><a href="/pcie/">PCIe Gen6 / Gen7</a><a href="{PROFILE}">Connect on LinkedIn ↗</a></div></footer></body></html>'''
